changeSet.sql:
-- Liquibase runs as auth_user, which OWNS `users` and is NOSUPERUSER NOBYPASSRLS, and -- `users` is FORCE ROW LEVEL SECURITY — FORCE binds the owner too. A repair spanning -- every tenant cannot set a single tenant GUC, so with the policy in force the UPDATE -- below would match ZERO rows, report success, and leave the duplicates for the index -- to trip over. Measured by 13-02 on this same database for user_branch_roles: 0 of 18 -- rows visible without a GUC, 18 after NO FORCE. Stand the policy down for the length -- of this changeset's transaction and put it back; a failure rolls both back together. ALTER TABLE users NO FORCE ROW LEVEL SECURITY;
-- RETENTION RULE, stated once and applied once. -- -- Within a (tenant_id, lower(email)) group of live rows, the SURVIVOR is the row with -- the greatest (last_login_at, updated_at, id), NULL last_login_at sorting last. In -- words: the account someone has actually logged into wins; if none or several have, -- the most recently touched wins; ties break on the greater id so the rule is total and -- gives the same answer on every replica. -- -- "Has been used" is the first key rather than "is newest" because these duplicates are -- case variants of ONE person's address: the row with login history is the one carrying -- their password, their TOTP secret and their audit trail, and picking the other one -- would silently lock out a working account in favour of an empty duplicate. WITH ranked AS ( SELECT id, row_number() OVER ( PARTITION BY tenant_id, lower(email) ORDER BY last_login_at DESC NULLS LAST, updated_at DESC, id DESC ) AS rn FROM users WHERE deleted_at IS NULL ) UPDATE users u SET is_active = false, -- Tombstoned, NOT deleted. The row survives in full, so every audit entry, -- order and journal line that references this user id still resolves — which is -- the whole reason this repair does not DELETE. What deleted_at buys over -- is_active alone is that the address is released: the new index skips -- soft-deleted rows, so the survivor can hold the lower-cased address. deleted_at = now(), updated_at = now() FROM ranked r WHERE u.id = r.id AND r.rn > 1;
-- Normalise the survivors. A row stored with any upper-case character can never be -- found by login, which lower-cases before the lookup — so a mixed-case row is an -- account that exists and cannot be used. The step above has already removed every -- live case-collision, so this cannot collide with another LIVE row; the NOT EXISTS -- guard covers the remaining case of a tombstoned row that already holds the -- lower-cased address, against which the unconditional uk_users_tenant_email still -- applies. A row the guard skips stays mixed-case: no worse than before, and it does -- not violate the new index, which keys on lower(email) either way. UPDATE users u SET email = lower(u.email), updated_at = now() WHERE u.deleted_at IS NULL AND u.email <> lower(u.email) AND NOT EXISTS ( SELECT 1 FROM users other WHERE other.tenant_id = u.tenant_id AND other.email = lower(u.email) AND other.id <> u.id);
ALTER TABLE users FORCE ROW LEVEL SECURITY;

DO $$
DECLARE
    remaining bigint;
BEGIN
    ALTER TABLE users NO FORCE ROW LEVEL SECURITY;

    SELECT count(*) INTO remaining
      FROM (SELECT 1
              FROM users
             WHERE deleted_at IS NULL
             GROUP BY tenant_id, lower(email)
            HAVING count(*) > 1) dupes;

    ALTER TABLE users FORCE ROW LEVEL SECURITY;

    IF remaining > 0 THEN
        RAISE EXCEPTION
            'auth-1.0.0-058: % (tenant_id, lower(email)) duplicate group(s) survive the repair. If this count is 0 when you query as a superuser, the repair ran under an ACTIVE row-level-security policy and matched nothing — check that the NO FORCE / FORCE bracket in changeset auth-1.0.0-058-repair-duplicate-tenant-emails is intact.', remaining;
    END IF;
END $$;
